    public void SetProject(Project p,bool render=true){Project=p;unsaved=false;Proposal=0;notice.Text="";Audience?.Install(null);Preview.Frame=null;Preview.Invalidate();generation++;loading=true;files.Items.Clear();foreach(var m in p.Materials)files.Items.Add(new Choice(Path.GetFileName(J.Str(m!,"path"))+" · "+J.Str(m!,"libraryRole"),J.Str(m!,"id")));var id=J.Str(p.Node,"currentFile");files.SelectedIndex=Math.Max(0,files.Items.Cast<Choice>().ToList().FindIndex(x=>x.Id==id));follow.Checked=J.Bool(p.Node["preferences"]!,"followSlides");loading=false;Search.Text="";RefreshActivities();if(render&&files.SelectedItem is Choice c){var m=p.Materials.First(x=>J.Str(x!,"id")==c.Id)!;if(IsPrivate(m))status.Text="المصدر خاص؛ اختر العرض لبدء المشاركة";else _=Render(m,J.Int(p.Node,"currentPage"));}UpdateMainState();RebuildFileSidebar();UpdateDock();}
    void LoadPreferences(){var sf=Path.Combine(Profile,"SharingPreferences.json");sharing=File.Exists(sf)?J.Load(sf):new JsonObject();showClock.Checked=J.Bool(sharing,"showTimer");overtime.Checked=J.Bool(sharing,"showOvertime");mute.Checked=sharing["muteSound"]==null||J.Bool(sharing,"muteSound");var af=Path.Combine(Profile,"UIAppearance.json");if(File.Exists(af)){var t=J.Load(af).GetValue<string>();ApplyTheme(t=="داكن"?1:t=="رملي"?2:0);}}
