    public void RefreshActivities(){var selected=(Activities.SelectedItem as Choice)?.Id;Activities.BeginUpdate();Activities.Items.Clear();if(Project!=null)foreach(var a in Project.Activities){var t=$"{J.Str(a!,"officialCode")} · {J.Str(a!,"title")} · {J.Num(a!,"duration")/60:0.##} د · {(J.Bool(a!,"approved")?"معتمد":"راجع")}";if(Normalize(t+J.Str(a!,"day")+J.Str(a!,"session")).Contains(Normalize(Search.Text)))Activities.Items.Add(new Choice(t,J.Str(a!,"id")));}Activities.EndUpdate();var idx=Activities.Items.Cast<Choice>().ToList().FindIndex(x=>x.Id==selected);if(idx>=0)Activities.SelectedIndex=idx;else if(Activities.Items.Count>0)Activities.SelectedIndex=0;else details.Controls.Clear();Activities.Invalidate();UpdateReviewCount();}
    static string Normalize(string s)=>new(s.Normalize(NormalizationForm.FormD).Where(c=>System.Globalization.CharUnicodeInfo.GetUnicodeCategory(c)!=System.Globalization.UnicodeCategory.NonSpacingMark).Select(c=>c=='ى'?'ي':char.ToLowerInvariant(c)).ToArray());
    public JsonNode? Selected=>Project?.Activities.FirstOrDefault(x=>J.Str(x!,"id")==((Choice?)Activities.SelectedItem)?.Id);
    public static bool IsPrivate(JsonNode m)=>J.Str(m,"libraryRole") is "trainer" or "learner"||Path.GetFileName(J.Str(m,"path")).Contains("دليل")||Path.GetFileName(J.Str(m,"path")).Contains("المدرب")||Path.GetFileName(J.Str(m,"path")).Contains("المتدرب");
    public static string Assessment(JsonNode a,JsonArray materials){var relevant=a["evidence"]!.AsArray().Where(e=>J.Num(e!,"seconds")>0&&(e!["timeKind"]==null||J.Str(e,"timeKind")==J.Str(a,"kind"))).ToList();var primary=relevant.Where(e=>materials.Any(m=>J.Str(m!,"id")==J.Str(e!,"fileID")&&J.Str(m!,"libraryRole") is "trainer" or "learner")).ToList();var values=primary.Select(e=>J.Num(e!,"seconds")).Distinct().ToList();if(primary.GroupBy(e=>J.Str(e!,"fileID")).Any(g=>g.Select(e=>J.Num(e!,"seconds")).Distinct().Count()>1))return "تعارض داخل الدليل";if(values.Count>1)return "تعارض بين الدليلين";if(values.Count==0)return "يحتاج مراجعة يدوية";if(relevant.Except(primary).Any(e=>Math.Abs(J.Num(e!,"seconds")-values[0])>.01))return "اختلاف العرض عن الدليل";return J.Bool(a,"approved")&&Math.Abs(values[0]-J.Num(a,"duration"))>.01?"اختلاف عن القيمة المعتمدة":"مقترح";}
    void ShowActivity(){details.SuspendLayout();details.Controls.Clear();var a=Selected;if(a==null||Project==null){details.ResumeLayout();return;}var id=J.Str(a,"id");void Label(string text)=>details.Controls.Add(new Label{Text=text,AutoSize=true,MaximumSize=new(440,0)});Label((J.Bool(a,"approved")?"معتمد · ":"")+Assessment(a,Project.Materials));Label("القيمة المعتمدة مستقلة عن ملاحظات المصادر؛ عرضها لا يغيّرها.");var title=new TextBox{Text=J.Str(a,"title"),Width=420,Multiline=true,Height=52,AccessibleName="اسم النشاط"};var minutes=new NumericUpDown{DecimalPlaces=2,Minimum=.01M,Maximum=1440,Value=(decimal)J.Num(a,"duration")/60,Width=100,AccessibleName="مدة النشاط بالدقائق"};details.Controls.Add(title);details.Controls.Add(minutes);
        var editors=new Dictionary<string,TextBox>();foreach(var field in new[]{"officialCode","day","session"}){var box=new TextBox{Text=J.Str(a,field),Width=420,AccessibleName=field=="officialCode"?"الرقم":field=="day"?"اليوم":"الجلسة"};editors[field]=box;details.Controls.Add(box);}var kind=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=180};kind.Items.AddRange(new object[]{"نشاط","استراحة","تأمل","جلسة","يوم"});kind.SelectedItem=J.Str(a,"kind");details.Controls.Add(kind);var presentation=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=420};presentation.Items.Add(new Choice("بلا ربط — تفعيل يدوي",""));foreach(var m in Project.Materials)presentation.Items.Add(new Choice(Path.GetFileName(J.Str(m!,"path")),J.Str(m!,"id")));presentation.SelectedIndex=Math.Max(0,presentation.Items.Cast<Choice>().ToList().FindIndex(x=>x.Id==J.Str(a,"presentationID")));details.Controls.Add(presentation);var start=new NumericUpDown{Minimum=0,Maximum=2000,Value=J.Int(a,"startPage"),AccessibleName="من شريحة"};var end=new NumericUpDown{Minimum=0,Maximum=2000,Value=J.Int(a,"endPage"),AccessibleName="إلى شريحة"};details.Controls.Add(start);details.Controls.Add(end);Label($"{J.Str(a,"day")} · {J.Str(a,"session")} · الأصلي {J.Num(a,"original")/60:0.##} د");
        details.Controls.Add(Btn("حفظ التعديل",()=>{Project.Edit(a,"title",JsonValue.Create(title.Text));Project.Edit(a,"duration",JsonValue.Create((double)minutes.Value*60));foreach(var (key,box)in editors)Project.Edit(a,key,key=="officialCode"&&box.Text==""?null:JsonValue.Create(box.Text));Project.Edit(a,"kind",JsonValue.Create(kind.SelectedItem?.ToString()??J.Str(a,"kind")));var pid=(presentation.SelectedItem as Choice)?.Id;Project.Edit(a,"presentationID",string.IsNullOrEmpty(pid)?null:JsonValue.Create(pid));Project.Edit(a,"startPage",start.Value==0?null:JsonValue.Create((int)start.Value));Project.Edit(a,"endPage",end.Value==0?null:JsonValue.Create((int)end.Value));Changed();RefreshActivities();},"التغيير الصريح يلغي اعتماد العنصر؛ إسناد القيمة نفسها يبقيه"));details.Controls.Add(Btn("اعتماد القيمة والربط",()=>{Approve(a);Changed();RefreshActivities();},"اعتماد العنصر المحدد فقط بقرارك"));details.Controls.Add(Btn("بدء النشاط",()=>{Begin(id);reviewWindow?.Close();},"يتطلب اعتمادًا محفوظًا"));details.Controls.Add(Btn("حذف النشاط",()=>{Project.Delete(id);Changed();RefreshActivities();},"حذف العنصر دون إعادة توليده"));
        foreach(var delta in new[]{-1,1}){var step=delta;details.Controls.Add(Btn(step<0?"تحريك لأعلى":"تحريك لأسفل",()=>{var i=Project.Activities.IndexOf(a);var j=i+step;if(j>=0&&j<Project.Activities.Count){var clone=a.DeepClone();Project.Activities.RemoveAt(i);Project.Activities.Insert(j,clone);Changed();RefreshActivities();}},"تغيير ترتيب العنصر المحدد"));}foreach(var e in a["evidence"]!.AsArray()){var ev=e!;Label($"{J.Str(ev,"filename")} · صفحة {J.Int(ev,"page")} · {J.Num(ev,"seconds")/60:0.##} د\n{J.Str(ev,"location")} · {J.Str(ev,"timeKind")}\n{J.Str(ev,"excerpt")}");details.Controls.Add(Btn("عرض المصدر",()=>PreviewSource(ev),"معاينة خاصة لا تغيّر الشريحة أو النشاط أو المؤقت"));}details.ResumeLayout();if(reviewWindow?.Tag as string=="dpi-ready")ScaleContent(details,DeviceDpi/96f);ApplyPalette(details);}
    void Approve(JsonNode a){if(Project==null)return;if(string.IsNullOrWhiteSpace(J.Str(a,"title"))||J.Num(a,"duration")<=0||J.Num(a,"duration")>86400)throw new InvalidDataException("اسم أو زمن غير صالح");if(a["presentationID"]!=null){var m=Project.Materials.FirstOrDefault(x=>J.Str(x!,"id")==J.Str(a,"presentationID"));var start=J.Int(a,"startPage");var end=J.Int(a,"endPage");if(m==null||start<1||end<start||end>J.Int(m,"pages"))throw new InvalidDataException("نطاق شرائح غير صالح");if(Project.Activities.Any(b=>b!=a&&J.Bool(b!,"approved")&&J.Str(b!,"presentationID")==J.Str(a,"presentationID")&&b!["startPage"]!=null&&start<=J.Int(b,"endPage")&&end>=J.Int(b,"startPage")))throw new InvalidDataException("تداخل مع نشاط معتمد");}a["approved"]=true;if(Project.Live.TryGetValue(J.Str(a,"id"),out var t))t.ChangeDuration(J.Num(a,"duration"),Clock.Now);}
    void AddActivity(){if(Project==null)return;var a=new JsonObject{["id"]=Guid.NewGuid().ToString(),["title"]="نشاط جديد",["kind"]="نشاط",["day"]="",["session"]="",["original"]=600,["duration"]=600,["approved"]=false,["evidence"]=new JsonArray()};Project.Activities.Add(a);Changed();RefreshActivities();Activities.SelectedIndex=Activities.Items.Count-1;}
    public void Begin(string id){if(Project==null)return;var a=Project.Activities.First(x=>J.Str(x!,"id")==id)!;if(!J.Bool(a,"approved")||J.Str(a,"kind") is "جلسة" or "يوم")throw new InvalidOperationException("اعتمد النشاط قبل بدئه");var old=J.Str(Project.Node,"currentActivity");if(old!=id&&Project.Live.TryGetValue(old,out var t))t.Pause(Clock.Now);Project.Node["currentActivity"]=id;free.Checked=false;Proposal=0;var clock=Project.Timer(id);if(!clock.Running)clock.Toggle(Clock.Now);if(a["presentationID"]!=null){var m=Project.Materials.FirstOrDefault(x=>J.Str(x!,"id")==J.Str(a,"presentationID"));if(m!=null&&!IsPrivate(m)){Project.Node["currentFile"]=J.Str(m,"id");loading=true;files.SelectedIndex=files.Items.Cast<Choice>().ToList().FindIndex(x=>x.Id==J.Str(m,"id"));loading=false;NavigateTo(Math.Max(0,J.Int(a,"startPage")-1));}}Changed();}
    Countdown? CurrentTimer(){if(Project==null)return null;if(free.Checked)return Project.Timer("free");var id=J.Str(Project.Node,"currentActivity");var a=Project.Activities.FirstOrDefault(x=>J.Str(x!,"id")==id);return a!=null&&J.Bool(a,"approved")?Project.Timer(id):null;}
    public void Mutate(Action<Countdown> f){var t=CurrentTimer()??throw new InvalidOperationException("اختر نشاطًا معتمدًا أو المؤقت الحر");foreach(var e in t.Poll(Clock.Now))Announce(e);f(t);Changed();}
    public void ConfirmExtension(){if(Proposal>0)Mutate(c=>c.Extend(Proposal*60,Clock.Now));Proposal=0;UpdateProposal();}
    void UpdateProposal(){proposalLabel.Text=$"+{Proposal} د";foreach(var b in confirms)b.Enabled=Proposal>0;}
    void Tick(){if(Project==null)return;var now=Clock.Now;foreach(var t in Project.Live.Values.ToArray())foreach(var e in t.Poll(now))Announce(e);var id=free.Checked?"free":J.Str(Project.Node,"currentActivity");var current=Project.Live.GetValueOrDefault(id);if(current==null){var stored=id=="free"?Project.Node["freeTimer"]:Project.Node["timers"]?[id];var activity=Project.Activities.FirstOrDefault(x=>J.Str(x!,"id")==id);if(stored!=null)current=Countdown.Read(stored);else if(activity!=null&&J.Bool(activity,"approved"))current=new Countdown(J.Num(activity,"duration"));}timerLabel.Text=current==null?"--:--":Countdown.Text(current.Remaining(now));if(panelTime!=null)panelTime.Text=timerLabel.Text;headerTime.Text=timerLabel.Text;dockTime.Text=timerLabel.Text;UpdateTimerState(current);var a=Project.Activities.FirstOrDefault(x=>J.Str(x!,"id")==id);Audience?.Timer(showClock.Checked&&!free.Checked&&a!=null&&J.Bool(a,"approved")&&J.Str(a,"kind")=="نشاط"?(overtime.Checked?timerLabel.Text:Countdown.Text(Math.Max(0,current?.Remaining(now)??0))):null);if(now>=noticeUntil)notice.Text="";if(!TestMode&&now-lastSave>=10){lastSave=now;if(unsaved||Project.Live.Values.Any(x=>x.Running))try{Save();}catch(Exception e){status.Text="تعذر حفظ الاسترداد: "+e.Message;}}}
    void Announce(int threshold){var pref=Project!.Node["preferences"]!;if(J.Bool(pref,"visual")){notice.Text=threshold==0?"انتهى الوقت — يستمر الزمن الإضافي":threshold==60?"تبقّت دقيقة واحدة":"تبقّت خمس دقائق";noticeUntil=Clock.Now+J.Num(pref,"noticeSeconds");}if(J.Bool(pref,"sound")&&(Audience==null||!mute.Checked))PlaySound(threshold);}
    public void PlaySound(int threshold){var pref=Project?.Node["preferences"];var volume=pref==null?.6:J.Num(pref,"volume");Audio.Play(threshold,volume,pref==null?0:J.Int(pref,"soundSet"));}
    public void SelectFile(string id){if(Project==null)return;var m=Project.Materials.First(x=>J.Str(x!,"id")==id)!;if(IsPrivate(m)){Private(m,0);return;}Project.Node["currentFile"]=id;Project.Node["currentPage"]=Project.Node["filePages"]?[id]?.GetValue<int>()??0;_=Render(m,J.Int(Project.Node,"currentPage"));Changed();}
    public void Navigate(int delta){if(Project!=null)NavigateTo(J.Int(Project.Node,"currentPage")+delta);}
    public void NavigateTo(int page){if(Project==null)return;var m=Project.Materials.FirstOrDefault(x=>J.Str(x!,"id")==J.Str(Project.Node,"currentFile"));if(m==null||IsPrivate(m))return;page=Math.Clamp(page,0,Math.Max(0,J.Int(m,"pages")-1));Project.Node["currentPage"]=page;Project.Node["filePages"]??=new JsonObject();Project.Node["filePages"]![J.Str(m,"id")]=page;_=Render(m,page);if(follow.Checked){var matches=Project.Activities.Where(a=>J.Bool(a!,"approved")&&J.Str(a!,"presentationID")==J.Str(m,"id")&&a!["startPage"]!=null&&J.Int(a,"startPage")<=page+1&&J.Int(a,"endPage")>=page+1).ToList();if(matches.Count==1&&J.Str(matches[0]!,"id")!=J.Str(Project.Node,"currentActivity")){var old=J.Str(Project.Node,"currentActivity");if(Project.Live.TryGetValue(old,out var t))t.Pause(Clock.Now);Project.Node["currentActivity"]=J.Str(matches[0]!,"id");if(J.Bool(Project.Node["preferences"]!,"autoStart"))Project.Timer(J.Str(matches[0]!,"id")).Toggle(Clock.Now);}}Changed();}
    public async Task Render(JsonNode m,int page){var token=++generation;var watch=Stopwatch.StartNew();try{var path=J.Str(m,"renderedPath");if(path=="")path=J.Str(m,"path");var image=await renderer.Render(path,page,()=>token==generation&&!IsDisposed);if(IsDisposed||token!=generation)return;Preview.Frame=image;Preview.Invalidate();Audience?.Install(image);pageLabel.Text=$"{page+1} / {J.Int(m,"pages")}";pageNumber.Value=Math.Clamp(page+1,1,2000);UpdateMainState();RenderSamples.Add(new JsonObject{["page"]=page+1,["local_update_ms"]=watch.Elapsed.TotalMilliseconds,["cached"]=renderer.LastCached,["raster_ms"]=renderer.LastRasterMilliseconds,["source_copies"]=renderer.SourceCopies});if(RenderSamples.Count>100)RenderSamples.RemoveAt(0);if(page+1<J.Int(m,"pages"))_=Prefetch(path,page+1,token);}catch(Exception e){if(token==generation&&!IsDisposed)status.Text="تعذر عرض الصفحة: "+e.Message;}}
    async Task Prefetch(string path,int page,int token){if(token!=generation)return;try{await renderer.Render(path,page,()=>token==generation&&!IsDisposed);}catch{/* A failed prefetch does not invalidate a displayed page. */}}
    void PreviewSource(JsonNode e){var m=Project?.Materials.FirstOrDefault(x=>J.Str(x!,"id")==J.Str(e,"fileID"));if(m!=null)Private(m,J.Int(e,"page")-1);}
    async void Private(JsonNode m,int page){using var f=new Form{Text="مصدر خاص — "+Path.GetFileName(J.Str(m,"path")),Width=1000,Height=800,RightToLeft=RightToLeft.Yes,StartPosition=FormStartPosition.CenterParent};var surf=new SlideSurface();var bar=Bar();f.AccessibleName="معاينة مصدر خاصة";int count=J.Int(m,"pages");var num=new NumericUpDown{Minimum=1,Maximum=Math.Max(1,count),Value=Math.Clamp(page+1,1,Math.Max(1,count)),Width=80};var rs=new RasterService();int request=0;async Task Show(){int token=++request;try{var img=await rs.Render(J.Str(m,"renderedPath")==""?J.Str(m,"path"):J.Str(m,"renderedPath"),(int)num.Value-1);if(!f.IsDisposed&&token==request){surf.Frame=img;surf.Invalidate();}}catch(Exception ex){if(!f.IsDisposed)MessageBox.Show(this,ex.Message);}}bar.Controls.Add(num);var go=new Button{Text="انتقال",AutoSize=true};go.Click+=async(_,_)=>await Show();bar.Controls.Add(go);bar.Controls.Add(new Label{Text="معاينة خاصة — الحقيبة والمؤقت والعرض المشترك ثابتة",AutoSize=true});var previous=new Button{Text="السابقة",AutoSize=true};var next=new Button{Text="التالية",AutoSize=true};previous.Click+=async(_,_)=>{num.Value=Math.Max(1,num.Value-1);await Show();};next.Click+=async(_,_)=>{num.Value=Math.Min(num.Maximum,num.Value+1);await Show();};bar.Controls.Add(previous);bar.Controls.Add(next);f.Controls.Add(surf);f.Controls.Add(bar);f.Shown+=async(_,_)=>await Show();ApplyPalette(f);f.ShowDialog(this);rs.Dispose();await Task.CompletedTask;}
    public void OpenAudience(){if(Audience==null||Audience.IsDisposed){Audience=new Audience();Audience.FormClosed+=(_,_)=>{Audience=null;panel?.Close();panel=null;};Audience.Install(Preview.Frame);PlaceAudience();Audience.Show();ShowPanel();}else Audience.Show();}
    void PlaceAudience(){if(Audience==null)return;var screens=Screen.AllScreens;var target=screens.Length>1?screens.FirstOrDefault(x=>x.DeviceName!=Screen.FromControl(this).DeviceName)??screens[0]:Screen.FromControl(this);Audience.WindowState=FormWindowState.Normal;Audience.Bounds=new Rectangle(target.WorkingArea.X+30,target.WorkingArea.Y+30,Math.Min(960,target.WorkingArea.Width-60),Math.Min(700,target.WorkingArea.Height-60));}
    public void ZoomAudience(){OpenAudience();Audience!.WindowState=Audience.WindowState==FormWindowState.Maximized?FormWindowState.Normal:FormWindowState.Maximized;ShowPanel();}
    void MoveAudience(){OpenAudience();var screens=Screen.AllScreens;var i=Array.FindIndex(screens,s=>s.DeviceName==Screen.FromControl(Audience!).DeviceName);var target=screens[(i+1)%screens.Length];Audience!.WindowState=FormWindowState.Normal;Audience.Location=target.WorkingArea.Location;status.Text=$"الشاشات المتاحة: {screens.Length}";}
    void ShowPanel(){if(Audience==null)return;if(Screen.AllScreens.Length>1)return;if(panel!=null&&!panel.IsDisposed){panel.Show();return;}panel=new Form{Text="Smart Training Presenter — Trainer Controls",ClientSize=new(650,108),TopMost=true,RightToLeft=RightToLeft.Yes,Font=Font,StartPosition=FormStartPosition.Manual};var title=new Label{Text=CurrentActivityTitle,Dock=DockStyle.Top,Height=24,TextAlign=ContentAlignment.MiddleCenter};var bar=Row(42);panelTime=new Label{Text=timerLabel.Text,AutoSize=true,Font=new("Consolas",20,FontStyle.Bold),RightToLeft=RightToLeft.No};bar.Controls.Add(IconButton("❯","الشريحة السابقة",()=>Navigate(-1),"الشريحة السابقة"));bar.Controls.Add(IconButton("❮","الشريحة التالية",()=>Navigate(1),"الشريحة التالية"));bar.Controls.Add(panelTime);bar.Controls.Add(IconButton("▶","مؤقت لوحة المدرب",()=>Mutate(t=>t.Toggle(Clock.Now)),"تشغيل أو إيقاف المؤقت"));bar.Controls.Add(Btn("+1",()=>{Proposal=Math.Min(1440,Proposal+1);UpdateProposal();},"اقتراح دقيقة"));bar.Controls.Add(Btn("−1",()=>{Proposal=Math.Max(0,Proposal-1);UpdateProposal();},"تقليل المقترح"));var confirm=Btn("تأكيد",ConfirmExtension,"تطبيق التمديد المقترح");confirms.Add(confirm);bar.Controls.Add(confirm);bar.Controls.Add(Btn("حجم الجمهور",ZoomAudience,"تكبير الجمهور وحده أو استعادة حجمه"));bar.Controls.Add(Btn("المدرب",()=>{Show();Activate();},"إظهار نافذة المدرب"));var hint=new Label{Text="مرّر المؤشر على أدوات اللوحة لعرض تلميحها",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleCenter,Font=new("Segoe UI",9)};foreach(Control c in bar.Controls){var control=c;control.MouseEnter+=(_,_)=>hint.Text=help.Text;control.MouseLeave+=(_,_)=>hint.Text="مرّر المؤشر على أدوات اللوحة لعرض تلميحها";}panel.Controls.Add(hint);panel.Controls.Add(bar);panel.Controls.Add(title);panel.FormClosed+=(_,_)=>{confirms.Remove(confirm);};ApplyPalette(panel);var area=Screen.FromControl(this).WorkingArea;panel.Location=new(area.Right-panel.Width-18,area.Bottom-panel.Height-18);panel.Show(this);UpdateProposal();}
    void Conflicts()=>ShowConflictBrowser();
    void OpenDialog(){using var d=new OpenFileDialog{Filter="ST Presenter|*.stpresenter"};if(d.ShowDialog(this)==DialogResult.OK)Guard(()=>{Save();SetProject(new Project(d.FileName));});}
    void ImportBag(){using var d=new FolderBrowserDialog{Description="اختر مجلد .stbag"};if(d.ShowDialog(this)==DialogResult.OK)Guard(()=>{Save();var p=Library.LoadBagPackage(d.SelectedPath);p.Pathname=Path.Combine(Profile,"ImportedProjects",Guid.NewGuid()+".stpresenter");SetProject(p);Changed();});}
    void ExportProject(){if(Project==null)return;using var d=new SaveFileDialog{Filter="ST Presenter|*.stpresenter"};if(d.ShowDialog(this)==DialogResult.OK)Guard(()=>Project.Save(d.FileName));}
    void ExportBag(){if(Project==null)return;using var d=new SaveFileDialog{Filter="ST Bag folder|*.stbag"};if(d.ShowDialog(this)==DialogResult.OK)Guard(()=>Library.ExportBag(Project,d.FileName));}
    async Task ImportDocument(){if(Project==null)return;using var d=new OpenFileDialog{Filter="PDF / PowerPoint|*.pdf;*.pptx;*.ppt"};if(d.ShowDialog(this)!=DialogResult.OK)return;try{var path=d.FileName;var hash=J.Hash(path);var rendered=path;if(Path.GetExtension(path).ToLowerInvariant()!=".pdf")rendered=await Office.Convert(path,Profile);var pages=await Pdf.Pages(rendered);var m=new JsonObject{["id"]=Guid.NewGuid().ToString(),["path"]=path,["hash"]=hash,["renderedPath"]=rendered,["pages"]=pages,["status"]="عرض ثابت محلي؛ لا حركات أو فيديو",["libraryRole"]="slides"};Project.Materials.Add(m);loading=true;files.Items.Add(new Choice(Path.GetFileName(path),J.Str(m,"id")));loading=false;Changed();}catch(Exception ex){Guard(()=>throw new IOException(ex.Message));}}
    void About(){var info=FileVersionInfo.GetVersionInfo(Environment.ProcessPath!);MessageBox.Show(this,$"Smart Training Presenter\n{info.ProductVersion}\nWindows x64\nإعداد: فهد عبدالله زبرماوي","حول التطبيق",MessageBoxButtons.OK,MessageBoxIcon.Information);}
    void Settings()=>ShowSettings();

}
public static class Audio {
    [DllImport("winmm.dll",CharSet=CharSet.Unicode)] static extern bool PlaySound(string file,nint module,uint flags);
    public static void Play(int threshold,double volume,int set){var name=set==0?(threshold==300?"alert-5m.wav":threshold==60?"alert-1m.wav":"alert-finish.wav"):(threshold==300?"Glass.wav":threshold==60?"Ping.wav":"Hero.wav");var source=Path.Combine(AppContext.BaseDirectory,"Sounds",name);if(!File.Exists(source))throw new FileNotFoundException("ملف الصوت غير متاح",source);var bytes=File.ReadAllBytes(source); // Scale PCM16 samples without changing system volume.
        using var stream=new MemoryStream(bytes);using var reader=new BinaryReader(stream);if(new string(reader.ReadChars(4))!="RIFF")throw new InvalidDataException("WAV غير مدعوم");stream.Position=12;int bits=0,format=0;while(stream.Position+8<=stream.Length){var tag=new string(reader.ReadChars(4));var len=reader.ReadUInt32();var start=stream.Position;if(tag=="fmt "){format=reader.ReadUInt16();stream.Position=start+14;bits=reader.ReadUInt16();}if(tag=="data"){if(bits!=16||format!=1)throw new InvalidDataException("يتطلب الصوت PCM16");for(long i=start;i+1<Math.Min(start+len,bytes.Length);i+=2){short sample=BitConverter.ToInt16(bytes,(int)i);var scaled=(short)(sample*Math.Clamp(volume,0,1));BitConverter.GetBytes(scaled).CopyTo(bytes,(int)i);}break;}stream.Position=start+len+(len%2);}var folder=Path.Combine(Path.GetTempPath(),"STP-Sounds");Directory.CreateDirectory(folder);var temp=Path.Combine(folder,name);File.WriteAllBytes(temp,bytes);if(!PlaySound(temp,0,0x20000|1|2))throw new IOException("تعذر إرسال الصوت للنظام");}
}

